<template>
  <BioNexusDialog ref="dialog" size="fullscreen" dialog-class="designer-table-dialog" body-class="designer-table-dialog-body" body-scroll="hidden" :prevent-close="dirty" :kicker="mode==='create'?'Nuevo objeto':'Editar objeto'" :title="mode==='create'?'Agregar tabla libre':'Editar tabla libre'" @before-close="requestClose" @close="reset">
    <section class="table-workspace">
      <aside class="table-tools"><BioNexusSectionPanel title="Estructura" icon="table" description="Define el tamaño y la distribución." variant="accent" compact><div class="fields-grid"><BioNexusFormField label="Filas" field-id="table-rows"><input id="table-rows" :value="draft.rows.length" class="bio-nexus-field" readonly></BioNexusFormField><BioNexusFormField label="Columnas" field-id="table-columns"><input id="table-columns" :value="columnCount" class="bio-nexus-field" readonly></BioNexusFormField><BioNexusFormField label="Ancho total" field-id="table-width"><input id="table-width" :value="tableSize.width" class="bio-nexus-field" type="number" min="40" max="2400" @change="setWidth($event.target.value)"></BioNexusFormField><BioNexusFormField label="Alto total" field-id="table-height"><input id="table-height" :value="tableSize.height" class="bio-nexus-field" type="number" min="18" max="1600" @change="setHeight($event.target.value)"></BioNexusFormField></div><div class="structure-actions"><BioNexusActionButton icon="add" variant="secondary" @click="addRow">Fila</BioNexusActionButton><BioNexusActionButton icon="add" variant="secondary" @click="addColumn">Columna</BioNexusActionButton><BioNexusActionButton icon="remove" variant="danger" :disabled="draft.rows.length===1" @click="removeRow">Fila</BioNexusActionButton><BioNexusActionButton icon="remove" variant="danger" :disabled="columnCount===1" @click="removeColumn">Columna</BioNexusActionButton></div></BioNexusSectionPanel>
      <BioNexusSectionPanel title="Celda seleccionada" icon="edit" :description="selectionLabel" variant="accent" compact><BioNexusFormField label="Contenido" field-id="table-cell-content" :help="selectedCell.content.length+' de máximo 500 caracteres'" wide><textarea id="table-cell-content" v-model="selectedCell.content" class="bio-nexus-field" maxlength="500"></textarea></BioNexusFormField><div class="token-list"><BioNexusActionButton v-for="token in tokens" :key="token.key" size="sm" variant="subtle" icon="data_object" @click="insertToken(token.key)">{{token.label}}</BioNexusActionButton></div><div class="fields-grid"><BioNexusFormField label="Fuente" field-id="cell-font"><BioNexusSearchableSelect id="cell-font" v-model="selectedCell.fontFamily" :options="fontOptions" /></BioNexusFormField><BioNexusFormField label="Tamaño" field-id="cell-size"><input id="cell-size" v-model.number="selectedCell.fontSize" class="bio-nexus-field" type="number" min="8" max="72"></BioNexusFormField><BioNexusFormField label="Texto" field-id="cell-text"><input id="cell-text" v-model="selectedCell.textColor" class="bio-nexus-field" type="color"></BioNexusFormField><BioNexusFormField label="Fondo" field-id="cell-background"><input id="cell-background" v-model="selectedCell.backgroundColor" class="bio-nexus-field" type="color"></BioNexusFormField></div><div class="format-actions"><BioNexusActionButton :variant="selectedCell.bold?'primary':'secondary'" icon="format_bold" @click="selectedCell.bold=!selectedCell.bold">Negrita</BioNexusActionButton><BioNexusActionButton :variant="selectedCell.italic?'primary':'secondary'" icon="format_italic" @click="selectedCell.italic=!selectedCell.italic">Cursiva</BioNexusActionButton><BioNexusActionButton :variant="selectedCell.underline?'primary':'secondary'" icon="format_underlined" @click="selectedCell.underline=!selectedCell.underline">Subrayado</BioNexusActionButton></div></BioNexusSectionPanel></aside>
      <section class="matrix-area"><header><div><strong>Diseñador matricial</strong><span>{{selectionLabel}}</span></div><div class="matrix-actions"><BioNexusActionButton icon="call_merge" variant="secondary" :disabled="selectedIndexes.length<2" @click="merge">Combinar</BioNexusActionButton><BioNexusActionButton icon="call_split" variant="secondary" :disabled="!canUnmerge" @click="unmerge">Separar</BioNexusActionButton></div></header><p class="matrix-help">Arrastra para seleccionar un rango. Usa Ctrl para agregar celdas y Shift para extender la selección.</p><div class="matrix-scroll"><table><thead><tr><th class="corner"></th><th v-for="column in columnCount" :key="column">{{columnName(column-1)}}</th></tr></thead><tbody><tr v-for="(row,rowIndex) in draft.rows" :key="rowIndex"><th>{{rowIndex+1}}</th><td v-for="(cell,columnIndex) in row.cells" :key="columnIndex" :class="{selected:isSelected(indexOf(rowIndex,columnIndex)),hidden:cell.hidden,merged:cell.rowSpan>1||cell.colSpan>1}" @pointerdown.prevent="beginSelection(indexOf(rowIndex,columnIndex),$event)" @pointerenter="extendSelection(indexOf(rowIndex,columnIndex))"><span>{{cellName(indexOf(rowIndex,columnIndex))}}</span><small>{{cell.content||'Vacía'}}</small></td></tr></tbody></table></div></section>
    </section><template #footer><BioNexusActionButton variant="secondary" icon="cancel" @click="requestClose">Cancelar</BioNexusActionButton><BioNexusActionButton variant="primary" :icon="mode==='create'?'create':'save'" :disabled="!dirty" @click="apply">{{mode==='create'?'Agregar':'Aplicar'}}</BioNexusActionButton></template>
  </BioNexusDialog><BioNexusConfirmDialog ref="discardDialog" />
</template>
<script setup>
import{computed,nextTick,ref}from"vue";import BioNexusActionButton from"@/components/ui/BioNexusActionButton.vue";import BioNexusConfirmDialog from"@/components/ui/BioNexusConfirmDialog.vue";import BioNexusDialog from"@/components/ui/BioNexusDialog.vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";import BioNexusSearchableSelect from"@/components/ui/BioNexusSearchableSelect.vue";import BioNexusSectionPanel from"@/components/ui/BioNexusSectionPanel.vue";import{createGenericTable,defaultGenericTableCell,genericTableFonts,genericTableSize,mergeGenericTableCells,normalizeGenericTable,resizeGenericTable,unmergeGenericTableCell}from"@/components/documents/designer/genericTableModel.js";
const props=defineProps({tokens:{type:Array,default:()=>[]}}),emit=defineEmits(["apply"]),dialog=ref(null),discardDialog=ref(null),mode=ref("create"),targetId=ref(null),draft=ref(createGenericTable()),original=ref(""),selectedIndex=ref(0),selectedIndexes=ref([0]),anchor=ref(0),dragging=ref(false),fontOptions=genericTableFonts.map(value=>({value,label:value}));const columnCount=computed(()=>draft.value.rows[0]?.cells.length||1),flatCells=computed(()=>draft.value.rows.flatMap(row=>row.cells)),selectedCell=computed(()=>flatCells.value[selectedIndex.value]||defaultGenericTableCell()),tableSize=computed(()=>genericTableSize(draft.value)),signature=computed(()=>JSON.stringify(draft.value)),dirty=computed(()=>signature.value!==original.value),selectionLabel=computed(()=>selectedIndexes.value.length===1?"Celda "+cellName(selectedIndexes.value[0]):selectedIndexes.value.length+" celdas seleccionadas"),canUnmerge=computed(()=>selectedCell.value.rowSpan>1||selectedCell.value.colSpan>1);function clone(value){return JSON.parse(JSON.stringify(value))}async function openCreate(){mode.value="create";targetId.value=null;draft.value=createGenericTable();original.value="";resetSelection();dialog.value?.open();await nextTick()}async function openEdit(value){mode.value="edit";targetId.value=value.id;draft.value=normalizeGenericTable(clone(value.table));original.value=signature.value;resetSelection();dialog.value?.open();await nextTick()}function resetSelection(){selectedIndex.value=0;selectedIndexes.value=[0];anchor.value=0}function indexOf(row,column){return row*columnCount.value+column}function columnName(index){let name="";for(let value=index+1;value>0;value=Math.floor((value-1)/26))name=String.fromCharCode(65+(value-1)%26)+name;return name}function cellName(index){return columnName(index%columnCount.value)+(Math.floor(index/columnCount.value)+1)}function isSelected(index){return selectedIndexes.value.includes(index)}function rectangular(start,end){const a={row:Math.floor(start/columnCount.value),column:start%columnCount.value},b={row:Math.floor(end/columnCount.value),column:end%columnCount.value},values=[];for(let row=Math.min(a.row,b.row);row<=Math.max(a.row,b.row);row++)for(let column=Math.min(a.column,b.column);column<=Math.max(a.column,b.column);column++)values.push(indexOf(row,column));return values}function beginSelection(index,event){dragging.value=true;if(event.ctrlKey||event.metaKey){selectedIndexes.value=isSelected(index)?selectedIndexes.value.filter(value=>value!==index):[...selectedIndexes.value,index];anchor.value=index}else if(event.shiftKey)selectedIndexes.value=rectangular(anchor.value,index);else{anchor.value=index;selectedIndexes.value=[index]}selectedIndex.value=index;globalThis.addEventListener("pointerup",()=>dragging.value=false,{once:true})}function extendSelection(index){if(!dragging.value)return;selectedIndexes.value=rectangular(anchor.value,index);selectedIndex.value=index}function setWidth(value){draft.value=resizeGenericTable(draft.value,Number(value),tableSize.value.height)}function setHeight(value){draft.value=resizeGenericTable(draft.value,tableSize.value.width,Number(value))}function addRow(){draft.value.rows.push({height:28,cells:Array.from({length:columnCount.value},()=>defaultGenericTableCell())})}function removeRow(){if(draft.value.rows.length>1){draft.value.rows.pop();resetSelection()}}function addColumn(){draft.value.columnWidths.push(160);for(const row of draft.value.rows)row.cells.push(defaultGenericTableCell());resetSelection()}function removeColumn(){if(columnCount.value>1){draft.value.columnWidths.pop();for(const row of draft.value.rows)row.cells.pop();resetSelection()}}function merge(){try{draft.value=mergeGenericTableCells(draft.value,selectedIndexes.value);const first=Math.min(...selectedIndexes.value);selectedIndexes.value=[first];selectedIndex.value=first}catch(error){globalThis.alert(error.message)}}function unmerge(){draft.value=unmergeGenericTableCell(draft.value,selectedIndex.value)}function insertToken(key){selectedCell.value.content+=(selectedCell.value.content?" ":"")+"{{"+key+"}}"}function apply(){if(!dirty.value)return;emit("apply",{mode:mode.value,id:targetId.value,table:clone(draft.value)});original.value=signature.value;dialog.value?.close()}async function requestClose(){if(dirty.value){const accepted=await discardDialog.value?.ask({kicker:"Confirmación",title:"Descartar cambios",message:"Hay cambios sin aplicar. ¿Deseas cerrar y descartarlos?",icon:"warning",variant:"danger",confirmIcon:"delete",confirmText:"Sí, cerrar y descartar",cancelText:"Continuar editando"});if(!accepted)return}dialog.value?.close()}function reset(){targetId.value=null;original.value="";dragging.value=false}defineExpose({openCreate,openEdit});
</script>
<style scoped>.table-workspace{display:grid;grid-template-columns:minmax(320px,390px) minmax(0,1fr);height:100%;min-height:0}.table-tools{display:grid;align-content:start;gap:12px;padding:14px;overflow:auto;border-right:1px solid var(--bio-nexus-color-border)}.fields-grid,.structure-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;align-items:start}.token-list,.format-actions,.matrix-actions{display:flex;flex-wrap:wrap;gap:6px}.matrix-area{display:grid;grid-template-rows:auto auto minmax(0,1fr);min-width:0;min-height:0;padding:16px;background:var(--bio-nexus-color-surface-soft)}.matrix-area>header{display:flex;justify-content:space-between;gap:12px}.matrix-area>header div:first-child{display:grid}.matrix-area>header span,.matrix-help{color:var(--bio-nexus-color-text-muted);font-size:12px}.matrix-scroll{min-width:0;min-height:0;overflow:auto;border:1px solid var(--bio-nexus-color-border-strong);background:#fff;scrollbar-gutter:stable}.matrix-scroll table{border-collapse:separate;border-spacing:0;min-width:max-content}.matrix-scroll th,.matrix-scroll td{box-sizing:border-box;min-width:92px;height:54px;padding:6px;border-right:1px solid var(--bio-nexus-color-border);border-bottom:1px solid var(--bio-nexus-color-border)}.matrix-scroll th{position:sticky;z-index:2;background:#edf3f7;text-align:center}.matrix-scroll thead th{top:0}.matrix-scroll tbody th{left:0;min-width:48px}.matrix-scroll .corner{left:0;z-index:3;min-width:48px}.matrix-scroll td{cursor:cell;user-select:none}.matrix-scroll td span,.matrix-scroll td small{display:block}.matrix-scroll td small{max-width:150px;overflow:hidden;color:var(--bio-nexus-color-text-muted);text-overflow:ellipsis;white-space:nowrap}.matrix-scroll td.selected{position:relative;background:var(--bio-nexus-color-info-soft);box-shadow:inset 0 0 0 2px var(--bio-nexus-color-primary)}.matrix-scroll td.merged{background:var(--bio-nexus-color-accent-soft)}.matrix-scroll td.hidden{opacity:.35;background:repeating-linear-gradient(135deg,#eef3f6 0 5px,#fff 5px 10px)}@media(max-width:900px){.table-workspace{grid-template-columns:1fr}.table-tools{max-height:42vh;border-right:0;border-bottom:1px solid var(--bio-nexus-color-border)}}</style>